// Auto-generated embedded PDF binary (37.5 KB) to guarantee instant client-side Blob download
// without SSR route interception in TanStack Start dev or production servers.
const RESUME_BASE64 = "";

let cachedBlobUrl: string | null = null;

export function getResumeBlobUrl(): string {
  if (typeof window === "undefined") return "/resume.pdf";
  if (cachedBlobUrl) return cachedBlobUrl;

  const binaryString = window.atob(RESUME_BASE64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  const blob = new Blob([bytes], { type: "application/pdf" });
  cachedBlobUrl = URL.createObjectURL(blob);
  return cachedBlobUrl;
}

export function handleResumeDownload(e?: React.MouseEvent) {
  if (e) {
    e.preventDefault();
    e.stopPropagation();
  }

  try {
    const blobUrl = getResumeBlobUrl();
    const link = document.createElement("a");
    link.href = blobUrl;
    link.download = "Chandrani_Bera_Resume.pdf";
    link.target = "_blank";
    link.rel = "noopener noreferrer";
    document.body.appendChild(link);
    link.click();
    setTimeout(() => {
      try {
        if (link.parentNode) {
          link.parentNode.removeChild(link);
        }
      } catch {
        // ignore
      }
    }, 500);
  } catch (err) {
    console.error("Resume download error, falling back to static asset:", err);
    window.location.href = "/src/assets/resume.pdf";
  }
}
